import { createHash, randomBytes } from 'node:crypto';
import prisma from './db';

/** sha256, not a slow KDF: keys are 32 random bytes, not human passwords, and
 *  lookup is on the alert hot path. */
export function hashKey(plain: string): string {
  return createHash('sha256').update(plain).digest('hex');
}

export function generateKey() {
  const plain = `oba_${randomBytes(32).toString('base64url')}`;
  return { plain, hash: hashKey(plain), prefix: plain.slice(0, 12) };
}

export async function resolveKey(plain: string) {
  if (!plain) return null;
  const row = await prisma.ingestKey.findUnique({ where: { hash: hashKey(plain) } });
  if (!row || row.revokedAt) return null;
  await prisma.ingestKey.update({ where: { id: row.id }, data: { lastUsedAt: new Date() } });
  return { userId: row.userId, keyId: row.id, prefix: row.prefix };
}

import { randomUUID } from 'node:crypto';
import type { Style } from './eventTypes';
import { clampDuration, renderTemplate, templateValues } from './template';
import type { Values } from './validate';

// The template functions themselves live in src/lib/template.ts so the
// dashboard preview can import them without pulling `node:crypto` into the
// browser bundle. Re-exported here because this module is the rendering entry
// point everything else already imports.
export { clampDuration, formatValue, renderTemplate, templateValues } from './template';

export type RenderConfig = {
  template: string;
  titleTemplate: string | null;
  style: Style;
  durationMs: number;
  imageUrl: string | null;
  soundUrl: string | null;
  soundVolume: number;
  locale: string;
};

export type AlertPayload = {
  id: string;
  eventType: string;
  title: string;
  text: string;
  message: string;
  style: Style;
  durationMs: number;
  imageUrl: string | null;
  soundUrl: string | null;
  soundVolume: number;
};

export function renderAlert(input: {
  eventTypeKey: string;
  values: Values;
  config: RenderConfig;
}): AlertPayload {
  const { eventTypeKey, values, config } = input;
  const message = typeof values.message === 'string' ? values.message : '';
  // message travels as its own payload field and must never be interpolated
  // into text/title, so it is excluded from the values templates render from.
  const forTemplate = templateValues(values);
  return {
    id: randomUUID(),
    eventType: eventTypeKey,
    title: config.titleTemplate ? renderTemplate(config.titleTemplate, forTemplate, config.locale) : '',
    text: renderTemplate(config.template, forTemplate, config.locale),
    message,
    style: config.style,
    durationMs: clampDuration(config.durationMs),
    imageUrl: config.imageUrl,
    soundUrl: config.soundUrl,
    soundVolume: config.soundVolume,
  };
}
// The rendering contract, in one place. Deliberately free of `node:crypto`
// (and of anything else Node-only) so the dashboard's live preview can import
// the very same functions the server renders with instead of keeping a second
// copy in sync by hand — the preview's whole purpose is to be a faithful
// stand-in for what streams. `randomUUID` lives in renderAlert (src/lib/render.ts),
// which the browser never imports.
import type { Values } from './validate';

export function formatValue(name: string, value: string | number, values: Values, locale: string): string {
  if (typeof value !== 'number') return value;
  const currency = typeof values.currency === 'string' ? values.currency : undefined;
  if (name === 'amount' && currency) {
    try {
      return new Intl.NumberFormat(locale, { style: 'currency', currency }).format(value);
    } catch {
      return new Intl.NumberFormat(locale).format(value); // unknown currency code
    }
  }
  return new Intl.NumberFormat(locale).format(value);
}

/** Single pass find-and-replace over a flat map: no expressions, no nesting, and
 *  substituted values are never rescanned, so donor text containing "{amount}"
 *  cannot pull in another field. */
export function renderTemplate(template: string, values: Values, locale: string): string {
  return template.replace(/\{(\w+)\}/g, (_m, name: string) => {
    const v = values[name];
    return v === undefined ? '' : formatValue(name, v, values, locale);
  });
}

/** Clamped in one place so the live path and the dashboard preview cannot
 *  disagree about how long an alert stays on screen. */
export function clampDuration(ms: number): number {
  return Math.min(30000, Math.max(100, Math.round(Number(ms) || 0)));
}

/** The `message` exclusion (Ruling 11): a donor's message travels as its own
 *  payload field and is never interpolated into text/title, so it is removed
 *  from the values a template renders from. Shared by renderAlert and the
 *  dashboard preview so the rule can only ever be implemented once. */
export function templateValues(values: Values): Values {
  const { message: _message, ...rest } = values;
  return rest;
}
// ponytail: in-process fan-out, so alerts only reach overlays connected to THIS
// instance. Ceiling: one Node process. Upgrade path: publish to Redis pub/sub and
// have each instance relay to its own local subscriber set.
type Send = (frame: string) => void;

const g = globalThis as unknown as { __alertHub?: Map<string, Set<Send>> };
const rooms: Map<string, Set<Send>> = (g.__alertHub ??= new Map());

export function subscribe(userId: string, send: Send): () => void {
  let set = rooms.get(userId);
  if (!set) rooms.set(userId, (set = new Set()));
  set.add(send);
  return () => {
    const s = rooms.get(userId);
    if (!s) return;
    s.delete(send);
    if (s.size === 0) rooms.delete(userId);
  };
}

export function publish(userId: string, data: unknown): number {
  const set = rooms.get(userId);
  if (!set || set.size === 0) return 0;
  const frame = `data: ${JSON.stringify(data)}\n\n`;
  let delivered = 0;
  for (const send of [...set]) {
    try {
      send(frame);
      delivered++;
    } catch {
      set.delete(send); // dead connection; the route's cleanup may not have run yet
    }
  }
  if (set.size === 0) rooms.delete(userId);
  return delivered;
}

export function countFor(userId: string): number {
  return rooms.get(userId)?.size ?? 0;
}

/** Test-only. */
export function __reset() {
  rooms.clear();
}

